'use strict';
const el=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let view='city',city='Praha',selected=null,savedAvailable=false,persistence=true,filterCity='all',flashTimer,notice='';
const TITLES={interior:"Studio kaváren & směny",organization:"Organizace firmy",live:"Živý provoz kaváren",leadership:"Plány vedení & příběhy",lab:"Kávová laboratoř",markets:"Trhy, nájmy & burza",menu:'Menu & vybavení',logistics:'Sklady & logistika',crises:'Problémy & pravomoci',planner:'Plánovač investic',scenarios:'Scénáře & cíle',city:'Města & expanze',stores:'Kavárny & franšízy',coffee:'Káva & značky',roasters:'Pražírny & zásoby',estates:'Vlastní plantáže',hq:'Sídlo & oddělení',people:'Lidé & regiony',rivals:'Konkurence & akvizice',board:'Board & vlastnictví',finance:'Finance & obchod'};
const POLICY={quality:'Kvalita',profit:'Zisk',growth:'Růst'};
try{const raw=localStorage.getItem('kavarna-v5')||localStorage.getItem('kavarna-v4')||localStorage.getItem('kavarna-v3')||localStorage.getItem('kavarna-v2')||localStorage.getItem('kavarna-v1');if(raw){const old=JSON.parse(raw);state=validateSave(old);savedAvailable=true;if(old.version===1)notice='Tvůj postup z první verze byl převeden. Přibyly samostatné šarže, pražírna a řízení firmy.'}}catch{notice='Uložený postup se nepodařilo načíst. Začala nová hra; původní soubor můžeš zkusit importovat.'}
function persist(){try{localStorage.setItem('kavarna-v5',JSON.stringify(state));persistence=true}catch{persistence=false}}
function placeToast9(){const node=el('toast');if(!node||node.style.display!=='block')return;const viewport=window.visualViewport,bottom=viewport?viewport.offsetTop+viewport.height:window.innerHeight;let edge=bottom;for(const bar of document.querySelectorAll('#uxRail11,.game-bottom6')){const rect=bar.getBoundingClientRect();if(rect.width&&rect.height&&rect.top<bottom&&rect.bottom>0&&!bar.closest('[hidden]'))edge=Math.min(edge,rect.top);}node.style.setProperty('--toast-bottom9',Math.max(16,window.innerHeight-edge+12)+'px');}
function hideToast9(){const node=el('toast');if(!node)return;if(node.hidePopover&&node.matches(':popover-open'))node.hidePopover();node.style.display='none';}
function toast(s){const node=el('toast');node.textContent=String(s);node.setAttribute('aria-atomic','true');node.style.display='block';if(node.showPopover){node.setAttribute('popover','manual');if(!node.matches(':popover-open'))node.showPopover();}placeToast9();clearTimeout(flashTimer);flashTimer=setTimeout(hideToast9,6500);}
window.addEventListener('resize',placeToast9);window.visualViewport?.addEventListener('resize',placeToast9);window.visualViewport?.addEventListener('scroll',placeToast9);
if(typeof ResizeObserver==='function'){const toastResize9=new ResizeObserver(placeToast9);new MutationObserver(()=>{for(const node of document.querySelectorAll('#uxRail11,.game-bottom6'))toastResize9.observe(node);placeToast9();}).observe(document.body,{childList:true,subtree:true});}
function show(html){el('modalContent').innerHTML=html;el('modal').showModal();}
function act(fn,msg){try{const result=fn();persist();render();if(msg)toast(msg);return result}catch(e){toast(e.message);return undefined}}
function goto(v){view=v;render();window.scrollTo({top:0,behavior:'smooth'})}
function number(n,d=0){return new Intl.NumberFormat('cs-CZ',{maximumFractionDigits:d}).format(n)}
function rows(arr){return `<div class="rows">${arr.map(([k,v])=>`<div class="row"><span>${k}</span><strong>${v}</strong></div>`).join('')}</div>`}
function option(value,text,selectedValue){return `<option value="${esc(value)}" ${String(value)===String(selectedValue)?'selected':''}>${esc(text)}</option>`}
function blendOptions(value){return state.blends.map(b=>option(b.id,b.name,value)).join('')}
function brandOptions(value){return state.brands.map(b=>option(b.id,b.name,value)).join('')}
function cityOptions(value,all=false){return (all?option('all','Všechna města',value):'')+CITIES.map(c=>option(c.name,c.name,value)).join('')}
function field(label,html){html=html.replace(/<(input|select|textarea)\b([^>]*)>/i,(tag,kind,attrs)=>/\baria-label(?:ledby)?=/.test(attrs)?tag:`<${kind} aria-label="${esc(label)}"${attrs}>`);return `<label class="field">${label}${html}</label>`}
function input(id,value,min,max,step=1){return `<input id="${id}" type="number" value="${value}" min="${min}" max="${max}" step="${step}">`}
function metric(t,v,n,css=''){return `<div class="metric"><div class="eyelabel">${t}</div><div class="value ${css}">${v}</div><div class="note">${n}</div></div>`}
function milestone(){const cities=new Set(state.stores.map(s=>loc(s.id).city)).size;return `<section class="card guide"><span class="eyelabel">${state.win?'MILNÍK SPLNĚN':'MEZINÁRODNÍ IMPÉRIUM'}</span><h3 style="margin-top:12px">Od zrna až k poslednímu šálku.</h3><p>Dvanáct poboček ve čtyřech městech. Pověst 75 a čtyři ziskové týdny za sebou.</p><div class="bar"><i style="width:${Math.min(100,state.stores.length/12*100)}%"></i></div><small>${state.stores.length} / 12 poboček · ${cities} / 4 města · pověst ${state.reputation}</small></section>`}
function news(limit=5){return state.logs.slice(0,limit).map(n=>`<div class="news"><span class="news-icon">↗</span><div>${esc(n.text)}<small>Týden ${n.week} · ${esc(n.detail)}</small></div></div>`).join('')}
function map(){const labels=LOCATIONS.filter(l=>l.city===city);return `<div class="map"><svg viewBox="0 0 800 460" preserveAspectRatio="none" role="img" aria-label="Schéma lokalit města ${city}"><defs><pattern id="blocks" width="86" height="65" patternUnits="userSpaceOnUse" patternTransform="rotate(-12)"><rect width="77" height="55" x="4" y="4" rx="5" fill="#dcded0"/><path d="M0 61H86M82 0V65" stroke="#f8f5ec" stroke-width="8"/></pattern></defs><rect width="800" height="460" fill="url(#blocks)"/><path d="M275 -20C480 90 190 164 320 244S390 340 310 490" stroke="#b7cfca" stroke-width="60" fill="none"/><path d="M100 180L720 310M130 355L680 100M60 100L760 195" stroke="#faf8f0" stroke-width="12"/>${labels.map(l=>`<text x="${l.x*8-35}" y="${l.y*4.6+43}" class="maplabel">${esc(l.name.toUpperCase())}</text>`).join('')}</svg>${labels.map(l=>{const s=state.stores.find(s=>s.id===l.id),r=occupant(l.id);return `<button class="pin ${s?'':r?'rival':'available'} ${selected===l.id?'selected':''}" style="left:${l.x}%;top:${l.y}%;${s?'background:'+brand(s.brand).color+';':''}" data-location="${l.id}" aria-label="${l.name}${r?' · '+r.name:''}">${s?'●':r?'×':'+'}</button>`}).join('')}<span class="map-meta">${city.toUpperCase()} · SCHÉMA LOKALIT</span></div>`}
function cityView(){const c=CITIES.find(c=>c.name===city),l=loc(selected)||LOCATIONS.find(l=>l.city===city),s=state.stores.find(s=>s.id===l.id),r=occupant(l.id),locked=!unlocked(city);return `<div class="grid"><section class="card"><div class="card-head"><div><h2>Tvoje další adresa</h2><p>${c.theme}</p></div><span class="badge">${CITIES.filter(c=>unlocked(c.name)).length} / ${CITIES.length} měst</span></div><div class="city-picker"><label class="field">Vybrat město<select id="citySelect">${CITIES.map(c=>option(c.name,c.name+(unlocked(c.name)?'':' · uzamčeno'),city)).join('')}</select></label><div class="sub">${LOCATIONS.filter(l=>l.city===city).length} lokalit · ${state.stores.filter(s=>loc(s.id).city===city).length} tvoje pobočky</div></div>${locked?`<div class="warning">Vstup do města: alespoň ${c.unlock} poboček a pověst ${c.reputation}. Máš ${state.stores.length} poboček a pověst ${state.reputation}.</div>`:''}${map()}<div class="map-legend"><span><i class="dot"></i>Tvoje značka</span><span><i class="dot open"></i>Volná lokalita</span><span><i class="dot rival"></i>Soupeř</span></div><div class="activity"><h3>Zprávy z impéria</h3>${news(4)}</div></section><div class="stack"><section class="card listing"><span class="eyelabel">${s?'TVOJE POBOČKA':r?'KONKURENČNÍ ADRESA':'PROSTOR PRO EXPANZI'}</span><h2>${l.name}</h2><span class="badge">${SEGMENTS[l.segment].name}</span>${rows([['Otevření',money(l.setup)],['Nájem / týden',money(l.rent)],['Základní poptávka',number(l.traffic)+' šálků'],['Očekávaná útrata',money(l.ideal)],['Doporučený tým',Math.ceil(l.traffic/400)+' baristé']])}${s?`<p class="sub">${esc(brand(s.brand).name)} · ${esc(blend(s.blend).name)}${s.franchise?' · franšíza':''}</p><button class="primary wide" data-goto="stores">Řídit pobočky →</button>`:r?`<p class="sub">Lokalitu provozuje ${esc(r.name)}. Získej ji převzetím firmy.</p><button class="soft wide" data-goto="rivals" style="margin-top:16px">Prozkoumat konkurenta →</button>`:`<button class="primary wide" data-open="${l.id}" ${locked||state.cash<l.setup||state.over?'disabled':''}>Otevřít vlastní kavárnu +</button><button class="soft wide" data-franchise="${l.id}" style="margin-top:10px" ${locked||state.reputation<65||state.over?'disabled':''}>Franšíza · ${money(l.setup*.25)}</button><p class="sub" style="margin-top:12px">Franšíza: 11 % tržeb, tvá firma dodává kávu. Mzdy a nájem platí partner. Pověst musí být 65.</p>`}</section>${milestone()}<section class="card"><span class="eyelabel">DALŠÍ OTEVŘENÁ MĚSTA</span><div class="city-buttons">${CITIES.filter(c=>c.name!==city).map(c=>`<button class="soft mini ${unlocked(c.name)?'':'locked'}" data-city="${esc(c.name)}">${esc(c.name)} ${unlocked(c.name)?'':'⌑'}</button>`).join('')}</div></section></div></div>`}
function storesView(){const shown=state.stores.filter(s=>filterCity==='all'||loc(s.id).city===filterCity);return `<div class="view-toolbar"><p class="intro">Při ruční změně ceny, týmu či marketingu se odpovídající pravomoc manažera vypne.</p><label class="field">Filtr města<select id="storeCityFilter">${cityOptions(filterCity,true)}</select></label></div><div class="cards">${shown.map(s=>{const l=loc(s.id),r=s.last;return `<section class="card"><div class="storehead"><div><span class="eyelabel">${l.city.toUpperCase()} · ${SEGMENTS[l.segment].name.toUpperCase()}</span><h2 style="margin-top:6px">${l.name}</h2></div><span class="badge" style="border-left:4px solid ${brand(s.brand).color}">${s.franchise?'Franšíza':s.manager?esc(s.manager.name.split(' ')[0]):'Osobní vedení'}</span></div>${r?rows([['Tržby firmy',money(r.revenue)],['Výsledek po nákladech',`<span class="${r.profit>=0?'good':'bad'}">${money(r.profit)}</span>`],['Obsloužení / ztracení hosté',r.served+' / '+r.lost]]):'<p class="sub">Provozní výsledky se objeví po prvním týdnu.</p>'}<div class="fields">${field('Značka',`<select data-store="${s.id}" data-store-field="brand">${brandOptions(s.brand)}</select>`)}${field('Odebíraná směs',`<select data-store="${s.id}" data-store-field="blend">${blendOptions(s.blend)}</select>`)}${field('Cena šálku (Kč)',`<input type="number" min="40" max="400" value="${s.price}" data-store="${s.id}" data-store-field="price">`)}${field(s.daily?'Požadovaný počet na každé směně':'Baristé',`<input type="number" min="1" max="7" value="${s.staff}" data-store="${s.id}" data-store-field="staff" ${s.franchise?'disabled':''}>`)}${field('Mzdový základ / týden',`<input type="number" min="5500" max="10000" step="500" value="${s.wage}" data-store="${s.id}" data-store-field="wage" ${s.franchise?'disabled':''}>`)}${field('Marketing / týden',`<input type="number" min="0" max="10000" step="500" value="${s.marketing}" data-store="${s.id}" data-store-field="marketing" ${s.franchise?'disabled':''}>`)}</div>${rows([['Kvalita provozu',s.quality+' / 100'],['Věrnost hostů',round(s.loyalty)+' / 80']])}<div class="bar"><i style="width:${s.quality}%"></i></div>${r?`<p class="sub">${r.reason}</p><button class="soft mini" data-report="${s.id}" style="margin-top:12px">Náklady & rozhodnutí ↗</button>`:''}${s.franchise?'<p class="sub" style="margin-top:12px">Partner zajišťuje běžný provoz. Tvá firma dostává 11 % tržeb a nese náklad dodané kávy.</p>':''}</section>`}).join('')}</div>`}
function coffeeView(){return `<div class="view-toolbar"><p class="intro">Každá receptura má vlastní zásoby a šarže. Změna receptury ovlivní až další pražení.</p><button class="primary" id="newBlend">Nová receptura +</button></div><div class="cards">${state.blends.map(b=>{const r=recipe(b);return `<section class="card coffee-card"><span class="eyelabel">RECEPTURA · ${b.packaging==='premium'?'PRÉMIOVÝ OBAL':b.packaging==='eco'?'RECYKLOVATELNÝ OBAL':'KLASICKÝ OBAL'}</span><div class="coffee-title">${esc(b.name)}</div><p class="sub">${esc(r.taste)}</p>${rows([['Kvalita receptury',coffeeQuality(b.id)+' / 100'],['Pražená zásoba',number(stock(b.id),1)+' kg'],['Kvalita aktuální zásoby',stockQuality(b.id)+' / 100'],['Cena na e-shopu',money(b.price)+' / kg'],['Odebírající kavárny',state.stores.filter(s=>s.blend===b.id).length],['Vývoj receptury',b.research+' / 6 bodů navíc']])}<div class="recipe-line"><span>${b.share} % ${ORIGINS[b.primary].name.split(' · ')[0]}</span><span>${100-b.share} % ${ORIGINS[b.secondary].name.split(' · ')[0]}</span><span>${['','Světlé','Střední','Tmavé'][b.roast]}</span></div><div class="actions"><button class="soft" data-edit-blend="${b.id}">Upravit recepturu</button><button class="soft" data-research="${b.id}" ${!state.departments.product||b.research>=6?'disabled':''}>Ochutnávka · 20 000 Kč</button></div><p class="sub" style="margin-top:12px">Zkus novou směs v jedné pobočce a porovnej její prodeje a marži ve Financích. Vývoj potřebuje oddělení Produkt.</p></section>`}).join('')}</div><div class="section-header"><div><span class="eyelabel">ZNAČKY KAVÁREN</span><h2>Jedna firma, různé zážitky</h2></div><button class="primary" id="newBrand">Nová značka +</button></div><div class="cards">${state.brands.map(b=>`<section class="card brand-card" style="border-top:5px solid ${b.color}"><div class="card-head"><h2>${esc(b.name)}</h2><span class="badge">${state.stores.filter(s=>s.brand===b.id).length} poboček</span></div><p class="sub">${CONCEPTS[b.concept].name}</p>${rows([['Pověst značky',round(b.reputation)+' / 100'],['Marketing značky / týden',money(b.budget)]])}<p class="sub">${b.concept==='express'?'Rychlá obsluha: kapacita baristy 450 šálků. Hodí se pro kanceláře a studenty.':b.concept==='specialty'?'Kvalita provozu +5. Hodí se pro náročné hosty a turisty; vyšší cena musí být podložená zážitkem.':'Kvalita +2. Sedí komunitním čtvrtím a pomáhá budovat pravidelné hosty.'}</p><button class="soft" data-edit-brand="${b.id}" style="margin-top:15px">Identita, koncept & marketing</button></section>`).join('')}</div>`}
function roastersView(){const needs=productionNeeds();return `<div class="view-toolbar"><p class="intro">Výroba plánuje podle odběrů kaváren, kontraktů a e-shopu. Zelená zrna nakupuj dopředu; expresní nákup automatiky je o 18 % dražší.</p><button class="primary" id="buyRoaster">Koupit pražírnu +</button></div><div class="cards">${state.roasters.map(r=>`<section class="card"><div class="card-head"><div><span class="eyelabel">${r.tenure6==='contract'?'SMLUVNÍ PRAŽENÍ':'VLASTNÍ VÝROBA'}</span><h2 style="margin-top:6px">${esc(r.name)}</h2></div><span class="badge">${r.auto?'Automatika':'Ruční plán'}</span></div>${rows([['Efektivní kapacita',roasterCapacity(r)+' kg zelené / týden'],['Nominální kapacita',r.capacity+' kg / směna'],['Technický stav',round(r.condition)+' / 100'],['Provoz a mzdy / týden',money(typeof economicRoasterFixed6==='function'?economicRoasterFixed6(r):r.upkeep+r.staff*r.wage+(r.manager?.salary||0))],['Využití minulý týden',r.last?round(r.last.utilization*100)+' %':'—']])}<div class="fields">${field('Směny',`<select data-roaster="${r.id}" data-rfield="shifts">${option(1,'Jedna směna',r.shifts)}${option(2,'Dvě směny',r.shifts)}</select>`)}${field('Pracovníci (2 na směnu)',`<input type="number" min="1" max="8" value="${r.staff}" data-roaster="${r.id}" data-rfield="staff" ${r.tenure6==='contract'?'disabled':''}>`)}${field('Priorita automatického plánu',`<select data-roaster="${r.id}" data-rfield="priority">${option('quality','Poptávka sítě',r.priority)}${option('margin','Nejlevnější receptury první',r.priority)}</select>`)}<label class="checkbox-line"><input type="checkbox" data-roaster="${r.id}" data-rfield="auto" ${r.auto?'checked':''}> Automaticky pražit</label></div><div class="actions"><button class="soft mini" data-maintain="${r.id}">${r.tenure6==='contract'?'Servis dodavatele · v ceně':'Servis · 18 000 Kč'}</button><button class="soft mini" data-upgrade-roaster="${r.id}" ${r.tenure6==='contract'?'disabled':''}>Kapacita +50 % · ${money(r.capacity*1800)}</button><button class="soft mini" data-manual-roast="${r.id}">Ruční šarže</button></div><div class="vote"><span class="avatar">${r.manager?r.manager.initials:'—'}</span><div style="flex:1"><strong>${r.manager?esc(r.manager.name):'Bez vedoucího výroby'}</strong><small>${r.manager?'Kontroluje stav a včas objedná servis. Dovednost zlepšuje chuť šarží.':'Vedoucí může hlídat údržbu a kvalitu.'}</small></div><button class="soft mini" data-hire-target="${r.id}" data-kind="roaster">${r.manager?'Změnit':'Najmout'}</button></div>${r.last?.decisions.length?`<details><summary>Výrobní report</summary><p class="sub">${r.last.decisions.map(esc).join('<br>')}</p></details>`:''}</section>`).join('')}</div><div class="split" style="margin-top:24px"><section class="card"><div class="card-head"><h2>Zelená káva</h2><button class="soft" id="orderBeans">Nakoupit zrna +</button></div><table class="data"><thead><tr><th>Původ</th><th>Na skladě</th><th>Na cestě</th></tr></thead><tbody>${Object.entries(ORIGINS).map(([id,o])=>`<tr><td>${esc(o.name)}</td><td>${number(greenAmount(id),1)} kg</td><td>${number(state.shipments.filter(s=>s.origin===id).reduce((a,s)=>a+s.kg,0),1)} kg</td></tr>`).join('')}</tbody></table><p class="sub" style="margin-top:14px">Dodavatel doručuje v následujícím týdnu. Vlastní sklizeň cestuje dva týdny.</p></section><section class="card"><h2>Pražené šarže</h2>${state.batches.length?`<table class="data"><thead><tr><th>Káva</th><th>kg</th><th>Stáří</th><th>Kvalita</th></tr></thead><tbody>${state.batches.map(b=>`<tr><td>${esc(blend(b.blend).name)}</td><td>${number(b.kg,1)}</td><td>${state.week-b.roastedWeek} t.</td><td>${round(batchQuality(b))}</td></tr>`).join('')}</tbody></table>`:'<p class="warning">Pražený sklad je prázdný. Příští týden musí být aktivní výroba, jinak kavárny neobslouží hosty.</p>'}<p class="sub" style="margin-top:14px">Po dvou týdnech se chuť postupně zhoršuje. Osm týdnů staré šarže se vyřadí. Výdej používá nejstarší kávu jako první.</p></section></div><section class="card" style="margin-top:24px"><h3>Odběrový plán</h3>${rows(state.blends.map(b=>[esc(b.name),number(needs[b.id]||0,1)+' kg / týden']))}${state.shipments.length?`<h3 style="margin-top:20px">Dodávky na cestě</h3>${state.shipments.map(s=>`<div class="row"><span>${esc(s.source)} · ${ORIGINS[s.origin].name}</span><strong>${number(s.kg,1)} kg · týden ${s.due}</strong></div>`).join('')}`:''}</section>`}
function estatesView(){return `<p class="intro">Vlastní plantáž znamená sklizeň po 12–14 týdnech a pravidelné výdaje. Kvalita, zdraví porostu a doprava rozhodují o tom, zda se vlastní původ vyplatí.</p><div class="cards">${state.estates.map(e=>`<section class="card"><div class="card-head"><div><span class="eyelabel">${e.country.toUpperCase()} · ${e.hectares} HA</span><h2 style="margin-top:7px">${esc(e.name)}</h2></div><span class="badge">Vlastní původ</span></div>${rows([['Do sklizně',(e.period-e.cycle)+' týdnů'],['Zdraví porostu',round(e.health)+' / 100'],['Provoz a mzdy / týden',money(e.upkeep+e.staff*e.wage+(e.manager?.salary||0)+(e.method==='quality'?3500:0))],['Základní výnos sklizně',round(e.yield*(1+e.yieldUpgrade*.25))+' kg'],['Závlaha',e.irrigation?'Instalovaná':'Bez závlahy']])}<div class="bar"><i style="width:${e.cycle/e.period*100}%"></i></div><div class="fields">${field('Pěstování',`<select data-estate="${e.id}" data-efield="method">${option('balanced','Vyvážené',e.method)}${option('quality','Výběrové · +3 kvalita, −15 % výnos',e.method)}${option('volume','Objem · +18 % výnos, −5 kvalita',e.method)}</select>`)}${field('Pracovníci',`<input type="number" min="1" max="10" value="${e.staff}" data-estate="${e.id}" data-efield="staff">`)}</div><div class="actions"><button class="soft mini" data-irrigation="${e.id}" ${e.irrigation?'disabled':''}>Závlaha · 90 000 Kč</button><button class="soft mini" data-expand-estate="${e.id}">Plocha +3 ha · ${money(e.cost*.25)}</button><button class="soft mini" data-hire-target="${e.id}" data-kind="estate">${e.manager?'Změnit správce':'Najmout správce'}</button></div>${e.manager?`<p class="sub" style="margin-top:12px">${e.manager.name} · ${money(e.manager.salary)}/týden. Hlídá porost a při zhoršení přijme pracovníka, pokud má firma rezervu.</p>`:''}${e.last?`<div class="warning">${e.last.risk?'Riziko: '+e.last.risk+'. ':'Běžné podmínky. '}${e.last.harvest?'Sklizeň '+e.last.harvest+' kg, kvalita '+e.last.quality+'. ':''}${e.last.decisions.map(esc).join(' ')}</div>`:''}</section>`).join('')}${ESTATES.filter(o=>!state.estates.some(e=>e.sourceId===o.id)).map(o=>`<section class="card purchase"><span class="eyelabel">PLANTÁŽ NA PRODEJ · ${o.country.toUpperCase()}</span><h2 style="margin-top:10px">${esc(o.name)}</h2><p class="sub" style="margin-top:8px">${ORIGINS[o.origin].taste}</p>${rows([['Kupní cena',money(o.cost)],['Plocha',o.hectares+' ha'],['Základní sklizeň',o.yield+' kg / '+o.period+' týdnů'],['Kvalita původu',o.quality+' / 100'],['Týdenní základní provoz',money(o.upkeep+4*2600)]])}<button class="primary wide" data-buy-estate="${o.id}" ${state.cash<o.cost?'disabled':''}>Koupit plantáž +</button><p class="sub" style="margin-top:12px">Cena nezahrnuje pracovní výdaje do první sklizně. Výdaje pěstování se promítnou do nákladu vlastních zrn.</p></section>`).join('')}</div>`}
function hqView(){return `<div class="view-toolbar"><p class="intro">Centrála roste s firmou. Každý zaměstnanec a oblastní ředitel potřebuje pracovní místo; zakladatel zabírá jedno.</p><span class="badge">${usedSeats()} / ${officeSeats()||'—'} míst</span></div><div class="cards">${state.offices.map(o=>`<section class="card"><span class="eyelabel">VLASTNÍ NEMOVITOST</span><h2 style="margin-top:10px">${esc(o.name)}</h2>${rows([['Pracovní místa',o.seats],['Provoz / týden',money(o.upkeep)]])}<p class="sub">Oddělení sdílejí kapacitu všech budov. Přestěhování nezruší zaměstnance ani projekty.</p></section>`).join('')}${OFFICE_OPTIONS.map(o=>`<section class="card purchase"><span class="eyelabel">KANCELÁŘE NA PRODEJ</span><h3 style="margin-top:10px">${esc(o.name)}</h3>${rows([['Kupní cena',money(o.cost)],['Pracovní místa',o.seats],['Provoz / týden',money(o.upkeep)]])}<button class="soft wide" data-buy-office="${o.id}" ${state.cash<o.cost||state.offices.length>=4?'disabled':''}>Koupit kanceláře +</button></section>`).join('')}</div><div class="section-header"><div><span class="eyelabel">VEDENÍ A PODPORA</span><h2>Oddělení firmy</h2></div></div><div class="cards">${Object.entries(DEPARTMENTS).map(([key,d])=>`<section class="card"><div class="card-head"><h2>${d.name}</h2><span class="badge">${state.departments[key]} zaměstnanců</span></div><p class="sub">${d.description}</p>${rows([['Mzda / člověk / týden',money(d.salary)],['Mzdy oddělení / týden',money(d.salary*state.departments[key])],['Nábor / člověk',money(8000)]])}<label class="field">Počet lidí<input type="number" min="0" max="30" value="${state.departments[key]}" data-department="${key}"></label>${key==='finance'?`<p class="sub" style="margin-top:14px">Doporučená rezerva: ${money(forecast().reserve)}. Úrok: ${(Math.max(.001,.002-state.departments.finance*.00015)*100).toFixed(3)} % / týden.</p>`:''}</section>`).join('')}</div><div class="section-header"><div><span class="eyelabel">PROJEKTY IT</span><h2>Digitální služby</h2></div></div><div class="cards">${Object.entries(state.projects).map(([key,p])=>`<section class="card"><div class="card-head"><h3>${key==='loyalty'?'Věrnostní aplikace':'E-shop s vlastní kávou'}</h3><span class="badge">${p.done?'Spuštěno':round(p.progress)+' %'}</span></div><p class="sub">${key==='loyalty'?'Zvyšuje věrnost hostů. Běží jen při obsazeném IT oddělení.':'Prodává balenou kávu ze zbývajících zásob. Obal a cena ovlivňují odběr; provoz potřebuje IT.'}</p><div class="bar"><i style="width:${p.progress}%"></i></div>${p.done?'<p class="sub">Provoz zajišťuje stávající IT tým.</p>':`<label class="field">Vývojový rozpočet / týden<input type="number" min="0" max="20000" step="2000" value="${p.budget}" data-project="${key}"></label><p class="sub" style="margin-top:10px">Týdenní postup: 5 bodů za IT člověka + 1 bod za 2 000 Kč rozpočtu. Projekt potřebuje nenulový rozpočet.</p>`}</section>`).join('')}</div>`}
function peopleView(){return `<div class="view-toolbar"><p class="intro">Manažeři respektují konkrétní pravomoci a marketingový limit. Regionální vedení může obsadit chybějící manažery a řešit slabou kvalitu.</p><button class="primary" id="newRegion">Oblastní ředitel +</button></div>${state.regions.length?`<div class="cards">${state.regions.map(r=>`<section class="card guide"><span class="eyelabel">REGIONÁLNÍ VEDENÍ</span><h2 style="margin-top:10px">${r.city}</h2><p>${r.manager.name} · ${money(r.manager.salary*1.4)} / týden</p><label class="checkbox-line"><input type="checkbox" data-region-auto="${r.city}" ${r.auto?'checked':''}> Automaticky doplňovat vedení a řešit kvalitu</label><div class="actions"><button class="soft" data-region-policy="${r.city}">Nastavit všechny pobočky</button></div>${r.last.length?`<p>${r.last.map(esc).join('<br>')}</p>`:''}</section>`).join('')}</div>`:''}<div class="cards">${state.stores.filter(s=>!s.franchise).map(s=>`<section class="card"><div class="card-head"><div><span class="eyelabel">${loc(s.id).city.toUpperCase()}</span><h2>${loc(s.id).name}</h2></div><button class="soft mini" data-hire-target="${s.id}" data-kind="store">${s.manager?'Změnit':'Najmout'}</button></div>${s.manager?`<div class="vote"><span class="avatar">${s.manager.initials}</span><div><strong>${s.manager.name}</strong><small>${s.manager.trait} · ${s.manager.skill}/100 · ${money(s.manager.salary)}/týden</small></div></div>`:'<p class="warning">Osobní vedení. Dovednost vedení 60/100; automatické změny se neprovádějí.</p>'}<div class="fields">${field('Cíl',`<select data-policy="${s.id}">${Object.entries(POLICY).map(([k,t])=>option(k,t,s.policy)).join('')}</select>`)}${field('Max. marketing / týden',`<input type="number" min="0" max="10000" step="500" value="${s.budget}" data-manager-budget="${s.id}">`)}</div><div class="rows">${[['staff','Měnit velikost týmu'],['price','Měnit cenu (max. ±5 Kč/týden)'],['marketing','Řídit marketing v limitu']].map(([k,t])=>`<div class="row"><label class="checkbox-line"><input type="checkbox" data-auto="${s.id}" data-key="${k}" ${s.auto[k]?'checked':''}> ${t}</label></div>`).join('')}</div><p class="sub">Kvalita: cena lokality +4, marketing 3 000 Kč. Růst: cena −5, marketing 5 000 Kč. Zisk: cena +9, marketing 1 800 Kč. Koncept značky upraví cílovou cenu. Tvůj limit má vždy přednost.</p>${s.last?.decisions.length?`<div class="warning">${s.last.decisions.map(esc).join('<br>')}</div>`:''}${s.manager?`<button class="quiet" data-fire="${s.id}" data-kind="store">Odvolat manažera</button>`:''}</section>`).join('')}</div>`}
function rivalsView(){return `<p class="intro">Tři firmy rozhodují podle vlastní strategie a hotovosti. Každý týden platí náklady; každé čtyři týdny hledají novou lokalitu. Ceny reagují na tvůj vstup do města.</p><div class="cards">${state.rivals.map(r=>`<section class="card rival-card"><div class="card-head"><h2>${esc(r.name)}</h2><span class="badge ${r.bankrupt?'neutral':''}">${r.acquired?'Převzata':r.bankrupt?'Bankrot':'Aktivní'}</span></div><p class="sub">${r.strategy==='volume'?'Objem a nízké ceny. Rychle expanduje do rušných lokalit.':r.strategy==='quality'?'Prémiová káva a vyšší ceny. Náročnější provoz, silná reputace.':'Komunitní značka a stabilní hosté. V konkurenčních městech snižuje cenu.'}</p>${rows([['Hotovost',money(r.cash)],['Pobočky',r.stores.length],['Poslední týdenní zisk',money(r.lastProfit)],['Pověst',round(r.reputation)+' / 100'],['Cenová pozice',round(r.priceFactor*100)+' % místního průměru'],['Cena převzetí',r.bankrupt?'—':money(rivalValuation(r))]])}${r.stores.length?`<div class="rival-locations">${r.stores.map(id=>`<button class="quiet" data-jump-location="${id}">${loc(id).city} · ${loc(id).name} ↗</button>`).join('')}</div>`:''}<button class="primary wide" data-acquire="${r.id}" ${r.bankrupt||state.cash<rivalValuation(r)?'disabled':''}>Převzít společnost →</button><p class="sub" style="margin-top:10px">Cena = hotovost + 85 % investice do poboček + 12× kladný týdenní zisk − 40 % dluhu. Převzetím získáš hotovost, pobočky a závazky.</p></section>`).join('')}</div><section class="card" style="margin-top:24px"><h3>Tržní pokrytí</h3><table class="data"><thead><tr><th>Město</th><th>Tvoje pobočky</th><th>Konkurence</th><th>Volné</th></tr></thead><tbody>${CITIES.map(c=>{const ls=LOCATIONS.filter(l=>l.city===c.name);return `<tr><td>${esc(c.name)}</td><td>${state.stores.filter(s=>loc(s.id).city===c.name).length}</td><td>${ls.filter(l=>occupant(l.id)).length}</td><td>${ls.filter(l=>!owned(l.id)&&!occupant(l.id)).length}</td></tr>`}).join('')}</tbody></table></section>`}
function boardView(){return `<div class="split"><div><p class="intro">Board zveřejňuje kritéria. Při podílu alespoň 50 % máš rozhodovací kontrolu; pod 50 % potřebuješ pro větší expanzi jeho mandát.</p>${['expansion','roastery','dividend'].map(type=>{const p=proposal(type),t={expansion:['Expanzní mandát','Investiční limit 3 miliony Kč pro nové pobočky a akvizice. Platíš ze skutečné hotovosti.'],roastery:['Rozšíření první pražírny','Investice 180 000 Kč zvýší její nominální kapacitu o 100 kg zelené kávy za směnu.'],dividend:['Dividenda zakladateli','Firma vyplatí 100 000 Kč. Zakladatel dostane část odpovídající svému vlastnickému podílu.']}[type];return `<section class="card" style="margin-top:20px"><div class="card-head"><h3>${t[0]}</h3><span class="badge">${p.votes.filter(v=>v.yes).length} / 3 pro</span></div><p class="sub">${t[1]}</p>${p.votes.map(v=>`<div class="vote"><span class="avatar" style="background:${v.yes?'#dce3cb':'#efdccd'}">${v.yes?'✓':'−'}</span><div><strong>${esc(v.name)} · ${v.yes?'PRO':'PROTI'}</strong><small>${v.reason}</small></div></div>`).join('')}<div class="actions"><button class="${p.passed?'primary':'soft'}" data-board="${type}" ${state.week<state.boardCooldown||state.over?'disabled':''}>${state.week<state.boardCooldown?'Zasedání v týdnu '+state.boardCooldown:'Hlasovat o návrhu'}</button>${!p.passed&&p.control?`<button class="soft" data-board-override="${type}" ${state.week<state.boardCooldown?'disabled':''}>Prosadit většinou · důvěra −10</button>`:''}</div></section>`}).join('')}</div><div class="stack"><section class="card guide"><span class="eyelabel">VLASTNICTVÍ FIRMY</span><h2 style="margin-top:12px">Kontrola má svou cenu.</h2>${rows([['Podíl zakladatele',state.founderShare+' %'],['Důvěra ve vedení',round(state.trust)+' / 100'],['Expanzní mandát',money(state.expansionBudget)],['Průměrný zisk / 4 týdny',money(proposal('expansion').avg)]])}<p>Investor vloží 2 miliony Kč za 25 procentních bodů firmy. Pod 50 % rozhodují u velké expanze hlasy boardu.</p><button class="soft wide" id="investor" ${state.founderShare<=25?'disabled':''}>Prodat 25 % · +2 miliony Kč</button></section>${milestone()}</div></div>`}
function financeView(){const h=state.history.at(-1),f=forecast();return `<div class="split"><section class="card"><div class="card-head"><h2>Výsledek firmy</h2><span class="badge">${h?'Týden '+h.week:'První týden čeká'}</span></div>${h?rows([['Tržby firmy bez DPH',money(h.revenue)],['Provozní náklady a daň',money(h.expenses)],['Spotřebovaná káva',money(h.cogs)],['Odpis staré kávy a jídla',money(h.spoil)],['Úroky',money(h.interest)],...(h.detail.propertyGain?[['Výsledek prodeje budov',money(h.detail.propertyGain)]]:[]),['Výsledek firmy',`<span class="${h.profit>=0?'good':'bad'}">${money(h.profit)}</span>`],['Provozní marže',number(h.margin*100,1)+' %'],['Změna hotovosti během tahu',money(h.cashChange)],['Nákupy a pražení během tahu',money(h.productionSpend)]]):'<p class="sub">Po odehrání týdne se objeví úplné výsledky firmy.</p>'}<p class="sub">Hotovost se mění také nákupem zásob. Pěstování se započítává do ceny sklizně; zisk zatíží až spotřebovaná vlastní zrna. Koupě budov a provozů je investice, jejíž účetní odpisy se účtují postupně.</p><div class="chart" role="img" aria-label="Provozní zisky posledních 12 týdnů">${state.history.slice(-12).map(h=>`<div class="${h.profit<0?'negative':''}" style="height:${Math.max(4,Math.abs(h.profit)/Math.max(1,...state.history.slice(-12).map(x=>Math.abs(x.profit)))*140)}px" title="Týden ${h.week}: ${money(h.profit)}"><small>${h.week}</small></div>`).join('')}</div></section><div class="stack"><section class="card"><h2>Kapitál & rezerva</h2>${rows([['Hotovost firmy',money(state.cash)],['Úvěr',money(state.debt)],['Osobní majetek',money(state.dividends)],['Rezerva na 6 týdnů fixních nákladů',money(f.reserve)],['Odhad hotovosti za 6 týdnů',state.departments.finance?money(f.projected):'Potřebuje Finance']])}<div class="actions"><button class="soft" id="loan">Úvěr až +400 000 Kč</button><button class="soft" id="repay" ${!state.debt?'disabled':''}>Splatit až 100 000 Kč</button></div><p class="sub" style="margin-top:10px">Úvěrový limit: ${money(400000+state.stores.length*100000)}. Odhad předpokládá stejné cash flow jako poslední týden.</p>${state.cash<f.reserve?'<div class="warning">Hotovost je pod šestitýdenní rezervou. Zvaž zpomalení investic.</div>':''}</section>${h?`<section class="card"><h3>Centrála & výroba</h3>${rows(Object.entries(h.detail).filter(([k])=>k!=='b2bCollections').map(([k,v])=>[({foodWholesale:'Pekárenské velkoobchodní tržby (bez DPH)',foodWholesaleCost:'Pekárenské velkoobchodní zásoby a doprava',foodFleetFixed:'Mzdy řidičů a údržba vozů',productPacking:'Balení produktů (zásoby)',productTransport:'Doprava produktů (zásoby)',localPayroll:'Rozdíl místních mezd',employerCost:'Odvody zaměstnavatele',capitalDepreciation:'Účetní odpisy',contractRoasting:'Úprava nákladů smluvního pražení',incomeTax:'Daň z výsledku (včetně vratky rezervy)',vatReserved:'DPH vyčleněná z tržeb',loanPrincipal:'Splátka jistiny (bez dopadu na zisk)',bakeryOperations:'Provoz pekáren',foodPurchases:'Nákupy jídla, surovin, energie a rozvoz (zásoby)',roasters:'Provoz pražíren',offices:'Kanceláře',departments:'Oddělení',regions:'Regionální vedení',estates:'Výdaje pěstování a dopravy',brands:'Marketing značek',projects:'Vývoj IT',penalties:'Pokuty za nedodání',warehouses:'Provoz skladů',transport:'Přeprava kávy',crises:'Problémy, servis a jednorázové výdaje',supplyPurchases:'Nákupy smluvních zásob (investice)',auctionRights:'Aukční práva (investice)',administration:'Koordinace velké sítě',development:'Vývoj, příběhy a burzovní poplatky',creditFees:'Poplatky úvěrové smlouvy',directors:'Ředitelé oddělení',b2bShipping:'B2B balení a doprava',brandCampaigns:'Cílené kampaně značek',brandIdentity:'Návrhy identity, etiket a změny značek',propertyFees:'Smlouvy a nemovitostní poplatky',propertyGain:'Výsledek prodeje budov',procurementPayments:'Platby dodavatelům zrn (zásoby)',procurementFees:'Sjednání dodavatelských odběrů'})[k],money(v)]))}</section>`:''}</div></div><section class="card" style="margin-top:24px"><div class="card-head"><h2>Velkoobchodní kontrakty</h2><button class="soft" id="newContract" ${state.contracts.length>=state.departments.sales?'disabled':''}>Nový odběratel +</button></div><p class="sub">Jeden obchodník může spravovat jeden kontrakt. Jednoduchá smlouva běží 12 týdnů, B2B smlouvy mají sjednanou délku a splatnost. Za nedodané množství platíš 15 % jeho prodejní hodnoty.</p>${state.contracts.length?`<table class="data"><thead><tr><th>Odběratel / káva</th><th>kg / týden</th><th>Cena / kg</th><th>Zbývá</th><th>Dodáno minule</th></tr></thead><tbody>${state.contracts.map(c=>`<tr><td>${esc(c.name)}<small class="table-sub">${esc(blend(c.blend).name)}</small></td><td>${c.kg}</td><td>${money(c.price)}</td><td>${c.remaining} t.</td><td>${c.last?c.last.delivered+' kg':'—'}</td></tr>`).join('')}</tbody></table>`:'<p class="empty sub">Založ Obchod v centrále a získej prvního odběratele vlastní kávy.</p>'}${h?rows([['Velkoobchod / poslední týden',money(h.wholesale)],['E-shop / poslední týden',money(h.online)],['Franšízové poplatky',money(h.franchise)]]):''}</section><section class="card" style="margin-top:24px"><h3>Výsledky poboček</h3><div class="table-scroll"><table class="data"><thead><tr><th>Kavárna / značka</th><th>Směs</th><th>Šálky</th><th>Tržby firmy</th><th>Zisk pobočky</th></tr></thead><tbody>${state.stores.map(s=>`<tr><td>${loc(s.id).city} · ${loc(s.id).name}<small class="table-sub">${esc(brand(s.brand).name)}${s.franchise?' · franšíza':''}</small></td><td>${esc(blend(s.blend).name)}</td><td>${s.last?.served??'—'}</td><td>${s.last?money(s.last.revenue):'—'}</td><td class="${s.last?.profit>=0?'good':'bad'}">${s.last?money(s.last.profit):'—'}</td></tr>`).join('')}</tbody></table></div><p class="sub" style="margin-top:14px">Zisk pobočky nezahrnuje náklady pražíren, centrály ani oddělení. Výsledek celé firmy je nahoře.</p></section>`}
function render(){el('title').textContent=TITLES[view];el('date').textContent=state.week+'. týden · '+new Date(2027,0,1+(state.week-1)*7).toLocaleDateString('cs-CZ',{month:'long',year:'numeric'});el('next').disabled=state.over||!state.stores.length;const h=state.history.at(-1);el('metrics').innerHTML=metric('HOTOVOST',money(state.cash),state.debt?'Dluh '+money(state.debt):'Vlastní kapitál · bez úvěru')+metric('TÝDENNÍ VÝSLEDEK',h?money(h.profit):'—',h?number(h.cups)+' prodaných šálků':'Odehraj první týden',h?(h.profit>=0?'good':'bad'):'')+metric('SÍŤ KAVÁREN',state.stores.length.toString().padStart(2,'0'),new Set(state.stores.map(s=>loc(s.id).city)).size+' měst · '+state.roasters.length+' pražíren')+metric('POVĚST ZNAČKY',state.reputation+' / 100',state.blends.length+' receptur · '+state.brands.length+' značek');document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const intro=notice?`<div class="tutorial"><span>${esc(notice)}</span><button class="soft mini" id="dismissNotice">Rozumím</button></div>`:state.week<=2?'<div class="tutorial"><span><strong>Edice 05:</strong> vyber první adresu a svůj návrh. Začínáš jen s 500 000 Kč. Zaplať prostor a vybavení, naber tým a sjednej dodávky kávy.</span><button class="soft mini" data-help>Jak hrát</button></div>':'';el('content').innerHTML=intro+(state.over?(state.sold?'<div class="warning"><strong>Firma byla prodána.</strong> Výnos zakladatele najdeš ve Financích.</div>':'<div class="warning"><strong>Platební neschopnost.</strong> Firma nemá hotovost. Načti uložený soubor nebo začni novou hru.</div>'):'')+({bakery:typeof bakeryView==='function'?bakeryView:null,management:typeof managementView==='function'?managementView:null,procurement:typeof procurementView==='function'?procurementView:null,season:typeof seasonsView==='function'?seasonsView:null,property:typeof propertyView==='function'?propertyView:null,branding:typeof brandingView==='function'?brandingView:null,guests:typeof guestsView==='function'?guestsView:null,business:typeof businessView==='function'?businessView:null,craft:typeof craftView==='function'?craftView:null,crew:typeof crewView==='function'?crewView:null,supply:typeof supplyView==='function'?supplyView:null,performance:typeof performanceView==='function'?performanceView:null,interior:typeof interiorView==='function'?interiorView:null,organization:typeof organizationView==='function'?organizationView:null,city:cityView,stores:storesView,coffee:coffeeView,roasters:roastersView,estates:estatesView,hq:hqView,people:peopleView,rivals:rivalsView,board:boardView,finance:financeView,menu:typeof menuView==='function'?menuView:null,logistics:typeof logisticsView==='function'?logisticsView:null,crises:typeof crisesView==='function'?crisesView:null,planner:typeof plannerView==='function'?plannerView:null,scenarios:typeof scenariosView==='function'?scenariosView:null,live:typeof liveView==='function'?liveView:null,leadership:typeof leadershipView==='function'?leadershipView:null,lab:typeof labView==='function'?labView:null,markets:typeof marketsView==='function'?marketsView:null}[view]());document.querySelector('footer span').textContent=persistence?'TAHOVÁ STRATEGIE · Ukládáno v tomto prohlížeči':'ULOŽENÍ V PROHLÍŽEČI NENÍ DOSTUPNÉ · Použij export';bind();}
function on(selector,handler,event='click'){document.querySelectorAll(selector).forEach(node=>node.addEventListener(event,()=>handler(node)))}
function setCity(name){city=name;selected=null;render()}
function confirmAction(title,text,action,label='Potvrdit'){show(`<h2>${title}</h2><p>${text}</p><div class="actions"><button class="primary" id="confirmAction">${label}</button><button class="soft" id="cancelAction">Zrušit</button></div>`);el('cancelAction').onclick=()=>el('modal').close();el('confirmAction').onclick=()=>{try{action();persist();render();el('modal').close();toast('Hotovo.')}catch(e){toast(e.message)}}}
function openDialog(id,franchise=false){const l=loc(id),cost=franchise?l.setup*.25:l.setup;show(`<span class="eyelabel">${l.city.toUpperCase()}</span><h2 style="margin-top:10px">${franchise?'Nová franšíza':'Nová kavárna'} · ${l.name}</h2><p>Investice ${money(cost)}. Po otevření zůstane ${money(state.cash-cost)}.</p><div class="fields">${field('Značka',`<select id="openBrand">${brandOptions(state.brands[0].id)}</select>`)}${field('Káva',`<select id="openBlend">${blendOptions(state.blends[0].id)}</select>`)}</div>${state.cash-cost<weeklyFixed()*4?'<div class="warning">Zůstane menší rezerva než čtyři týdny současných fixních nákladů. Nová pobočka přidá další výdaje.</div>':''}<button class="primary wide" id="openConfirm" style="margin-top:20px">${franchise?'Otevřít franšízu':'Otevřít kavárnu'} +</button>`);el('openConfirm').onclick=()=>{try{openStore(id,el('openBrand').value,el('openBlend').value,franchise);persist();render();el('modal').close();toast('Nová pobočka otevřena.')}catch(e){toast(e.message)}}}
function blendDialog(id){const b=id?blend(id):{name:'Nová směs',primary:'colombia',secondary:'ethiopia',share:75,roast:2,packaging:'classic',price:590};show(`<span class="eyelabel">${id?'RECEPTURA':'VÝVOJ NOVÉ KÁVY · 15 000 Kč'}</span><h2 style="margin-top:10px">${id?'Upravit kávu':'Vlastní nová směs'}</h2><div class="fields">${field('Název kávy',`<input id="blendName" value="${esc(b.name)}" maxlength="40">`)}${field('Cena balené kávy / kg',input('blendPrice',b.price,250,1200,10))}${field('Hlavní původ',`<select id="blendPrimary">${Object.entries(ORIGINS).map(([k,o])=>option(k,o.name,b.primary)).join('')}</select>`)}${field('Doplňkový původ',`<select id="blendSecondary">${Object.entries(ORIGINS).map(([k,o])=>option(k,o.name,b.secondary)).join('')}</select>`)}${field('Podíl hlavního původu (%)',input('blendShare',b.share,50,100,5))}${field('Pražení',`<select id="blendRoast">${[1,2,3].map(n=>option(n,['','Světlé','Střední','Tmavé'][n],b.roast)).join('')}</select>`)}${field('Obal balené kávy',`<select id="blendPackaging">${option('classic','Klasický · 20 Kč/kg',b.packaging)}${option('premium','Prémiový · 45 Kč/kg, +10 % zájem',b.packaging)}${option('eco','Recyklovatelný · 32 Kč/kg',b.packaging)}</select>`)}</div><div id="recipePreview" class="warning"></div><p class="sub">Původ a pražicí profil mění chuť. Staré šarže zůstávají beze změny. Káva se dostane k hostům až po výrobě a přiřazení pobočkám.</p><button class="primary wide" id="blendConfirm" style="margin-top:20px">${id?'Uložit recepturu':'Vyvinout novou kávu'} ✓</button>`);const read=()=>({name:el('blendName').value.trim(),primary:el('blendPrimary').value,secondary:el('blendSecondary').value,share:Number(el('blendShare').value),roast:Number(el('blendRoast').value),packaging:el('blendPackaging').value,price:Number(el('blendPrice').value)});const preview=()=>{const r=recipe({...read(),research:b.research||0});el('recipePreview').textContent='Kvalita receptury '+round(r.quality)+'/100 · zelená káva '+money(r.cost)+'/kg · zrna a pražení '+money((r.cost+55)/.84)+'/kg pražené kávy.'};['blendPrimary','blendSecondary','blendShare','blendRoast'].forEach(k=>el(k).onchange=preview);preview();el('blendConfirm').onclick=()=>{try{const data=read();if(id)updateBlend(id,data);else createBlend(data);persist();render();el('modal').close();toast('Káva připravena.')}catch(e){toast(e.message)}}}
function brandDialog(id){const b=id?brand(id):{name:'Nová značka',concept:'specialty',color:'#a37453',budget:0};show(`<span class="eyelabel">IDENTITA KAVÁREN</span><h2 style="margin-top:10px">${id?'Upravit značku':'Založit další značku'}</h2><div class="fields">${field('Název značky',`<input id="brandName" maxlength="40" value="${esc(b.name)}">`)}${field('Barva značky',`<input id="brandColor" type="color" value="${b.color}">`)}${field('Koncept',`<select id="brandConcept">${Object.entries(CONCEPTS).map(([k,c])=>option(k,c.name+' · založení '+money(c.cost),b.concept)).join('')}</select>`)}${field('Marketing značky / týden',input('brandBudget',b.budget,0,20000,1000))}</div><p>Koncept ovlivňuje kapacitu obsluhy, kvalitu i to, které místní hosty přitahuje. Změna konceptu existující značky stojí polovinu jeho zakládací ceny.</p><button class="primary wide" id="brandConfirm">${id?'Uložit identitu':'Založit značku'} +</button>`);el('brandConfirm').onclick=()=>{try{const data={name:el('brandName').value.trim(),concept:el('brandConcept').value,color:el('brandColor').value,budget:Number(el('brandBudget').value)};if(id)updateBrand(id,data);else{const created=createBrand(data.name,data.concept,data.color);created.budget=clamp(data.budget,0,20000)}persist();render();el('modal').close();toast('Značka uložena.')}catch(e){toast(e.message)}}}
function hireDialog(id,kind){show(`<span class="eyelabel">${kind==='store'?'VEDENÍ KAVÁRNY':kind==='roaster'?'VEDENÍ VÝROBY':'SPRÁVA PLANTÁŽE'}</span><h2 style="margin-top:10px">Vyber manažera</h2><p>Nábor ${money(Math.max(4000,12000-state.departments.hr*1500))}. Mzda vedoucího je navíc k pracovníkům provozu.</p>${MANAGERS.map((m,i)=>`<div class="vote"><span class="avatar">${m.initials}</span><div style="flex:1"><strong>${esc(m.name)}</strong><small>${m.trait} · ${m.skill}/100<br>${money(m.salary)} / týden</small></div><button class="soft mini" data-hire-choice="${i}">Najmout</button></div>`).join('')}<button class="quiet" id="fireInDialog">Odvolat stávajícího manažera</button>`);on('[data-hire-choice]',b=>{try{hire(id,Number(b.dataset.hireChoice),kind);persist();render();el('modal').close();toast('Manažer nastoupil.')}catch(e){toast(e.message)}});el('fireInDialog').onclick=()=>{try{fire(id,kind);persist();render();el('modal').close();toast('Manažer odvolán.')}catch(e){toast(e.message)}}}
function purchaseRoasterDialog(){show(`<span class="eyelabel">${r.tenure6==='contract'?'SMLUVNÍ PRAŽENÍ':'VLASTNÍ VÝROBA'}</span><h2 style="margin-top:10px">Koupit pražírnu</h2><div class="fields">${field('Název provozu',`<input id="roasterName" maxlength="40" value="Nová pražírna">`)}${field('Typ pražírny',`<select id="roasterType">${ROASTER_OPTIONS.map(o=>option(o.id,o.name+' · '+money(o.cost),'artisan')).join('')}</select>`)}</div><div id="roasterPreview" class="warning"></div><button class="primary wide" id="roasterConfirm">Koupit pražírnu +</button>`);const preview=()=>{const o=ROASTER_OPTIONS.find(o=>o.id===el('roasterType').value);el('roasterPreview').textContent=o.capacity+' kg za směnu týdně. Dva pracovníci na směnu, mzda 5 500 Kč/osoba + základní provoz '+money(o.upkeep)+'/týden.'};el('roasterType').onchange=preview;preview();el('roasterConfirm').onclick=()=>{try{buyRoaster(el('roasterType').value,el('roasterName').value);persist();render();el('modal').close();toast('Pražírna koupena.')}catch(e){toast(e.message)}}}
function manualRoastDialog(id){const r=state.roasters.find(r=>r.id===id);show(`<h2>Ruční šarže · ${esc(r.name)}</h2><p>Volná týdenní kapacita ${roasterCapacity(r)-(r.manualUsed||0)} kg zelené kávy. Ztráta pražením 16 %, zpracování 55 Kč/kg zelené kávy.</p><div class="fields">${field('Káva',`<select id="manualBlend">${blendOptions(state.blends[0].id)}</select>`)}${field('Zelená káva (kg)',input('manualKg',25,1,roasterCapacity(r)-(r.manualUsed||0)))}</div><button class="primary wide" id="manualConfirm" style="margin-top:20px">Upražit šarži</button>`);el('manualConfirm').onclick=()=>{try{manualRoast(id,el('manualBlend').value,Number(el('manualKg').value));persist();render();el('modal').close();toast('Šarže upražena.')}catch(e){toast(e.message)}}}
function orderDialog(){show(`<h2>Objednat zelená zrna</h2><p>Dodání v týdnu ${state.week+1}. Platíš nyní; zrna použiješ po příjezdu. Automatické zásobování umí expresní nákup, ale stojí o 18 % více.</p><div class="fields">${field('Původ',`<select id="orderOrigin">${Object.entries(ORIGINS).map(([k,o])=>option(k,o.name+' · '+money(getBeanCost(k))+'/kg','brazil')).join('')}</select>`)}${field('Množství (kg)',input('orderKg',100,1,2500))}</div><button class="primary wide" id="orderConfirm" style="margin-top:20px">Objednat zrna →</button>`);el('orderConfirm').onclick=()=>{try{orderBeans(el('orderOrigin').value,Number(el('orderKg').value));persist();render();el('modal').close();toast('Zrna objednána.')}catch(e){toast(e.message)}}}
function regionDialog(){show(`<h2>Oblastní ředitel</h2><p>Nábor 20 000 Kč. Ředitel zabírá místo v centrále a dostává 1,4× mzdu běžného manažera.</p><div class="fields">${field('Region',`<select id="regionCity">${CITIES.filter(c=>!state.regions.some(r=>r.city===c.name)).map(c=>option(c.name,c.name,'Praha')).join('')}</select>`)}${field('Ředitel',`<select id="regionManager">${MANAGERS.map((m,i)=>option(i,m.name+' · '+money(m.salary*1.4)+'/týden',1)).join('')}</select>`)}</div><button class="primary wide" id="regionConfirm" style="margin-top:20px">Najmout regionální vedení</button>`);el('regionConfirm').onclick=()=>{try{addRegion(el('regionCity').value,Number(el('regionManager').value));persist();render();el('modal').close();toast('Region má vlastní vedení.')}catch(e){toast(e.message)}}}
function regionPolicyDialog(city){show(`<h2>Pravidla regionu · ${city}</h2><p>Nastavení se použije na všechny tvé vlastní kavárny v regionu. Zapne manažerům pravomoci upravovat tým, cenu a marketing.</p><div class="fields">${field('Cíl',`<select id="regionPolicy">${Object.entries(POLICY).map(([k,t])=>option(k,t,'quality')).join('')}</select>`)}${field('Limit marketingu / pobočka / týden',input('regionBudget',3000,0,10000,500))}</div><button class="primary wide" id="regionPolicyConfirm" style="margin-top:20px">Použít na pobočky</button>`);el('regionPolicyConfirm').onclick=()=>{try{assignRegion(city,el('regionPolicy').value,Number(el('regionBudget').value));persist();render();el('modal').close();toast('Regionální pravidla nastavena.')}catch(e){toast(e.message)}}}
function contractDialog(){show(`<h2>Velkoobchodní odběratel</h2><p>Smlouva na 12 týdnů. Cena vychází z ceníku kávy a dovednosti obchodního oddělení. Kavárny mají při výdeji zásob přednost.</p><div class="fields">${field('Dodávaná káva',`<select id="contractBlend">${blendOptions(state.blends[0].id)}</select>`)}${field('Odběr / týden (kg)',input('contractKg',20,5,100))}</div><button class="primary wide" id="contractConfirm" style="margin-top:20px">Podepsat kontrakt</button>`);el('contractConfirm').onclick=()=>{try{signContract(el('contractBlend').value,Number(el('contractKg').value));persist();render();el('modal').close();toast('Kontrakt podepsán.')}catch(e){toast(e.message)}}}
function report(id){const s=state.stores.find(s=>s.id===id),r=s.last;show(`<span class="eyelabel">TÝDEN ${state.week-1} · ${loc(id).city.toUpperCase()}</span><h2 style="margin-top:10px">${loc(id).name}</h2>${rows([['Tržby bez DPH',money(r.revenue)],['Výsledek kavárny',money(r.profit)]])}${rows(Object.entries(r.detail).map(([k,v])=>[({productRevenue:'Tržby hotových produktů bez DPH',productCost:'Spotřebované zásoby hotových produktů',payroll:'Odvody zaměstnavatele',overtime:'Přesčasy',utilities:'Energie a voda',cardFees:'Platby kartou',vat:'DPH z tržeb',depreciation:'Odpis investice',equipment:'Údržba vybavení',wages:'Mzdy baristů',manager:'Manažer',rent:'Nájem nebo údržba prostoru',ingredients:'Mléko, obaly a ostatní suroviny',overhead:'Energie a provoz',marketing:'Marketing',coffee:'Spotřebovaná káva'})[k]||esc(k),money(v)]))}<p><strong>${r.reason}</strong></p><p>Obslouženo ${r.served} hostů, ztraceno ${r.lost}. Motivace ${r.morale}/100. Spotřeba kávy ${r.used} kg.</p><h3>Rozhodnutí vedení</h3><p>${r.decisions.length?r.decisions.map(esc).join('<br>'):'Tento týden žádné automatické změny.'}</p>`)}
function bind(){on('[data-location]',b=>{selected=b.dataset.location;render()});on('[data-city]',b=>setCity(b.dataset.city));if(el('citySelect'))el('citySelect').onchange=()=>setCity(el('citySelect').value);if(el('storeCityFilter'))el('storeCityFilter').onchange=()=>{filterCity=el('storeCityFilter').value;render()};on('[data-goto]',b=>goto(b.dataset.goto));on('[data-open]',b=>openDialog(b.dataset.open));on('[data-franchise]',b=>openDialog(b.dataset.franchise,true));on('[data-jump-location]',b=>{city=loc(b.dataset.jumpLocation).city;selected=b.dataset.jumpLocation;goto('city')});on('[data-report]',b=>report(b.dataset.report));on('[data-help]',help);if(el('dismissNotice'))el('dismissNotice').onclick=()=>{notice='';render()};
 on('[data-store]',i=>{const s=state.stores.find(s=>s.id===i.dataset.store),k=i.dataset.storeField;act(()=>{guard();if(['brand','blend'].includes(k)){if(k==='brand'&&!brand(i.value)||k==='blend'&&!blend(i.value))throw Error('Neplatný výběr.');s[k]=i.value}else{const n=Number(i.value),range={price:[40,400],staff:[1,7],wage:[5500,10000],marketing:[0,10000]}[k];if(!Number.isInteger(n)||n<range[0]||n>range[1])throw Error('Hodnota musí být celé číslo od '+range[0]+' do '+range[1]+'.');s[k]=n;if(k==='staff'&&typeof setShifts5==='function')setShifts5(s.id,[n,n,n]);if(s.manager&&['price','staff','marketing'].includes(k)){s.auto[k]=false;toast('Ruční změna vypnula odpovídající pravomoc manažera.')}}});},'change');
 on('[data-hire-target]',b=>hireDialog(b.dataset.hireTarget,b.dataset.kind));on('[data-fire]',b=>act(()=>fire(b.dataset.fire,b.dataset.kind),'Manažer odvolán.'));on('[data-policy]',i=>act(()=>{guard();state.stores.find(s=>s.id===i.dataset.policy).policy=i.value},'Cíl uložen.'),'change');on('[data-manager-budget]',i=>act(()=>{guard();const n=Number(i.value);if(!Number.isInteger(n)||n<0||n>10000)throw Error('Rozpočet musí být od 0 do 10 000 Kč.');state.stores.find(s=>s.id===i.dataset.managerBudget).budget=n},'Limit uložen.'),'change');on('[data-auto]',i=>act(()=>{guard();state.stores.find(s=>s.id===i.dataset.auto).auto[i.dataset.key]=i.checked}),'change');on('[data-region-auto]',i=>act(()=>{guard();state.regions.find(r=>r.city===i.dataset.regionAuto).auto=i.checked}),'change');on('[data-region-policy]',b=>regionPolicyDialog(b.dataset.regionPolicy));
 on('[data-edit-blend]',b=>blendDialog(b.dataset.editBlend));on('[data-research]',b=>act(()=>researchBlend(b.dataset.research),'Receptura optimalizována.'));on('[data-edit-brand]',b=>brandDialog(b.dataset.editBrand));if(el('newBlend'))el('newBlend').onclick=()=>blendDialog();if(el('newBrand'))el('newBrand').onclick=()=>brandDialog();if(el('newRegion'))el('newRegion').onclick=regionDialog;
 on('[data-roaster]',i=>act(()=>{guard();const r=state.roasters.find(r=>r.id===i.dataset.roaster),k=i.dataset.rfield;if(k==='auto')r.auto=i.checked;else if(k==='priority')r.priority=i.value;else{const n=Number(i.value);if(!Number.isInteger(n)||k==='staff'&&(n<1||n>8)||k==='shifts'&&![1,2].includes(n))throw Error('Neplatný počet pracovníků nebo směn.');r[k]=n}},'Plán výroby uložen.'),'change');on('[data-maintain]',b=>act(()=>maintainRoaster(b.dataset.maintain),'Servis dokončen.'));on('[data-upgrade-roaster]',b=>{const r=state.roasters.find(r=>r.id===b.dataset.upgradeRoaster);confirmAction('Rozšířit '+esc(r.name)+'?', 'Investice '+money(r.capacity*1800)+'. Kapacita vzroste o 50 %, provozní výdaje o 15 %.',()=>upgradeRoaster(r.id),'Rozšířit')});on('[data-manual-roast]',b=>manualRoastDialog(b.dataset.manualRoast));if(el('buyRoaster'))el('buyRoaster').onclick=purchaseRoasterDialog;if(el('orderBeans'))el('orderBeans').onclick=orderDialog;
 on('[data-buy-estate]',b=>{const o=ESTATES.find(e=>e.id===b.dataset.buyEstate);confirmAction('Koupit '+o.name+'?', 'Cena '+money(o.cost)+'. První sklizeň za '+o.period+' týdnů. Pravidelné výdaje před první sklizní: nejméně '+money((o.upkeep+10400)*o.period)+'.',()=>buyEstate(o.id),'Koupit plantáž')});on('[data-irrigation]',b=>act(()=>irrigation(b.dataset.irrigation),'Závlaha instalována.'));on('[data-expand-estate]',b=>{const e=state.estates.find(e=>e.id===b.dataset.expandEstate);confirmAction('Rozšířit '+e.name+'?', 'Cena '+money(e.cost*.25)+'. Větší plocha zvýší základní výnos a nároky na zaměstnance.',()=>expandEstate(e.id),'Rozšířit plantáž')});on('[data-estate]',i=>act(()=>{guard();const e=state.estates.find(e=>e.id===i.dataset.estate);if(i.dataset.efield==='method'){if(!['quality','volume','balanced'].includes(i.value))throw Error('Neplatné pěstování.');e.method=i.value}else{const n=Number(i.value);if(!Number.isInteger(n)||n<1||n>10)throw Error('Plantáž potřebuje 1–10 pracovníků.');e.staff=n}},'Plán plantáže uložen.'),'change');
 on('[data-buy-office]',b=>{const o=OFFICE_OPTIONS.find(o=>o.id===b.dataset.buyOffice);confirmAction('Koupit '+o.name+'?', 'Cena '+money(o.cost)+', kapacita '+o.seats+' míst, týdenní provoz '+money(o.upkeep)+'.',()=>buyOffice(o.id),'Koupit sídlo')});on('[data-department]',i=>act(()=>setDepartment(i.dataset.department,Number(i.value)),'Oddělení upraveno.'),'change');on('[data-project]',i=>act(()=>startProject(i.dataset.project,Number(i.value)),'Rozpočet projektu uložen.'),'change');
 on('[data-acquire]',b=>{const r=state.rivals.find(r=>r.id===b.dataset.acquire);confirmAction('Převzít '+r.name+'?', 'Cena '+money(rivalValuation(r))+'. Získáš '+r.stores.length+' poboček, hotovost '+money(r.cash)+' a dluh '+money(r.debt)+'. Nové pobočky zvýší odběr kávy a provozní výdaje.',()=>acquireRival(r.id),'Převzít společnost')});on('[data-board]',b=>{const p=act(()=>board(b.dataset.board));if(p)toast(p.approved?'Board schválil návrh.':'Board návrh zamítl; důvody jsou u hlasů.')});on('[data-board-override]',b=>confirmAction('Prosadit rozhodnutí většinovým podílem?', 'Použiješ rozhodovací kontrolu. Důvěra ve vedení klesne o 10 bodů.',()=>board(b.dataset.boardOverride,true),'Prosadit rozhodnutí'));if(el('investor'))el('investor').onclick=()=>confirmAction('Přijmout investora?', 'Firma dostane 2 miliony Kč. Tvůj podíl klesne ze '+state.founderShare+' % na '+(state.founderShare-25)+' %. Pod 50 % potřebuješ pro větší expanzi souhlas boardu.',raiseCapital,'Přijmout investici');if(el('loan'))el('loan').onclick=()=>act(takeLoan,'Úvěr připsán.');if(el('repay'))el('repay').onclick=()=>act(repay,'Úvěr částečně splacen.');if(el('newContract'))el('newContract').onclick=contractDialog;
}
function help(){show(`<span class="eyelabel">KAVÁRNA · EDICE 02</span><h2 style="margin-top:10px">Firma od plantáže po kavárnu</h2><p><strong>Každý tah znamená týden.</strong> Přijedou dodávky, výroba doplní zásoby, manažeři provedou povolené změny, kavárny obslouží hosty a firma zaplatí výdaje. Potom rozhodují soupeři.</p><p><strong>Začátek:</strong> otevři druhou kavárnu a nastav jí vhodnou kávu. Najmi manažera, ale ponech si rezervu. Po dvou pobočkách a pověsti 45 se otevře Brno.</p><p><strong>Vlastní káva:</strong> různé směsi mají oddělené šarže. Každé kavárně přiděl recepturu. Při změně chuti stará zásoba nezmizí. Nakupuj zrna dopředu; automatika koupí chybějící expresně za příplatek.</p><p><strong>Výroba a plantáže:</strong> pražírny mají směny, kapacitu, pracovníky a opotřebení. Plantáže platíš každý týden, sklízí po 12–14 týdnech a zrna cestují dva týdny.</p><p><strong>Centrála:</strong> kanceláře dovolují obsadit HR, Finance, Obchod, Produkt a IT. Nábor a mzdy jsou skutečné výdaje. IT vyvíjí věrnostní aplikaci a e-shop.</p><p><strong>Řízení:</strong> manažer se drží cíle a povolených změn. Oblastní ředitel umí najímat vedení a řešit kvalitu. Board má veřejná kritéria; většinový vlastník drží kontrolu.</p><p><strong>Cíl:</strong> 12 poboček ve 4 městech, pověst 75 a 4 ziskové týdny. Soupeři mohou obsadit volné lokality; jejich firmy můžeš převzít.</p><p class="sub">Ekonomické hodnoty jsou herní model, nikoli skutečné ceny či pravidla měst. Vše je účtováno v Kč. Hra zjednodušuje daně, odpisy i logistiku. Postup se ukládá lokálně v tomto prohlížeči; soubor umožní přenos.</p><div class="actions"><button class="soft" id="helpSave">Uložit soubor</button><button class="soft" id="helpImport">Načíst soubor</button><button class="soft" id="helpReset">Nová hra</button></div>`);el('helpSave').onclick=downloadSave;el('helpImport').onclick=()=>el('import').click();el('helpReset').onclick=confirmNew;}
function downloadSave(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.href=url;a.download='kavarna-v5-tyden-'+state.week+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Postup uložen do souboru.');}
function confirmNew(){show('<h2>Začít novou firmu?</h2><p>Postup v tomto prohlížeči se nahradí. Před začátkem můžeš uložit současnou hru do souboru.</p><div class="actions"><button class="soft" id="saveBeforeReset">Uložit současnou hru</button><button class="primary" id="resetConfirm">Začít novou hru</button></div>');el('saveBeforeReset').onclick=downloadSave;el('resetConfirm').onclick=()=>{state=fresh();view='city';city='Praha';selected=null;filterCity='all';notice='';persist();render();el('modal').close();toast('Nová firma založena.');window.scrollTo({top:0})};}
el('nav').onclick=e=>{const b=e.target.closest('[data-view]');if(b)goto(b.dataset.view)};el('next').onclick=()=>{const previouslyWon=state.win;const h=act(nextWeek);if(h){toast('Týden uzavřen: '+money(h.profit));if(state.over||state.win&&!previouslyWon){show(`<h2>${state.over?'Firma nemá hotovost':'Mezinárodní kávové impérium!'}</h2><p>${state.over?'Zkontroluj, které výdaje vyčerpaly hotovost. Můžeš načíst starší uložený soubor nebo začít znovu.':'Dvanáct poboček ve čtyřech městech, silná pověst a čtyři ziskové týdny. Můžeš pokračovat.'}</p><button class="soft" id="finishHelp">Ukládání & nová hra</button>`);el('finishHelp').onclick=help}}};el('help').onclick=help;el('save').onclick=downloadSave;el('newgame').onclick=confirmNew;el('close').onclick=()=>el('modal').close();el('modal').onclick=e=>{if(e.target===el('modal')){const r=el('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)el('modal').close()}};
el('import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Soubor je příliš velký.');const candidate=validateSave(JSON.parse(await f.text()));state=candidate;view='city';city='Praha';selected=null;filterCity='all';notice='Hra načtena. Postup z první verze se automaticky převede.';persist();render();el('modal').close();toast('Postup načten.')}catch(err){toast(err.message)}e.target.value='';};
if(document.modelContext?.registerTool){const controller=new AbortController();window.addEventListener('pagehide',()=>controller.abort(),{once:true});const tools=[{name:'read_coffee_game',description:'Read coffee company state: cash, stores, recipes, production, departments and competitors.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:input=>{if(input&&Object.keys(input).length)throw Error('No arguments allowed.');return {week:state.week,cash:round(state.cash),reputation:state.reputation,stores:state.stores.map(s=>({id:s.id,city:loc(s.id).city,blend:s.blend,manager:s.manager?.name,profit:s.last?.profit})),blends:state.blends.map(b=>({id:b.id,name:b.name,stock:round(stock(b.id)),quality:coffeeQuality(b.id)})),roasters:state.roasters.map(r=>({id:r.id,capacity:roasterCapacity(r),condition:round(r.condition)})),departments:{...state.departments},rivals:state.rivals.map(r=>({name:r.name,stores:r.stores.length,cash:round(r.cash),bankrupt:r.bankrupt}))}}}, {name:'advance_coffee_week',description:'Advance the game by one week, applying production, manager decisions, costs and competitor actions.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(input&&Object.keys(input).length)throw Error('No arguments allowed.');const h=nextWeek();persist();render();return {week:h.week,profit:h.profit,cash:h.cash,cups:h.cups,over:state.over}}}];for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:controller.signal})).catch(()=>{})}catch{}}
render();
